import events from './events.json' with {type:'json'};

const TOOL_NAME = 'events_list';
const DEFAULT_PAGE_SIZE = 2;
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;

function encodeCursor(index) {
  return Buffer.from(`cursor:${index}`, 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  let decoded;
  try {
    decoded = Buffer.from(cursor, 'base64').toString('utf8');
  } catch {
    throw new Error('Invalid cursor');
  }
  const match = /^cursor:(\d+)$/.exec(decoded);
  if (!match) throw new Error('Invalid cursor');
  const index = Number(match[1]);
  if (!Number.isInteger(index) || index < 0 || index > events.length) {
    throw new Error('Invalid cursor');
  }
  return index;
}

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'List events with cursor-based pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string' },
          page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE },
        },
        additionalProperties: false,
      },
    },
  ];
}

function validateArguments(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  let pageSize = DEFAULT_PAGE_SIZE;
  if ('page_size' in args) {
    const v = args.page_size;
    if (typeof v !== 'number' || !Number.isInteger(v)) {
      throw new Error('page_size must be an integer');
    }
    if (v < MIN_PAGE_SIZE || v > MAX_PAGE_SIZE) {
      throw new Error(`page_size must be between ${MIN_PAGE_SIZE} and ${MAX_PAGE_SIZE}`);
    }
    pageSize = v;
  }

  let startIndex = 0;
  if ('cursor' in args) {
    const v = args.cursor;
    if (typeof v !== 'string') {
      throw new Error('cursor must be a string');
    }
    startIndex = decodeCursor(v);
  }

  return { startIndex, pageSize };
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error('Unknown tool');
  }
  const { startIndex, pageSize } = validateArguments(args);

  const slice = events.slice(startIndex, startIndex + pageSize);
  const nextStart = startIndex + pageSize;

  const result = {
    events: slice,
    count: slice.length,
  };
  if (nextStart < events.length) {
    result.next_cursor = encodeCursor(nextStart);
  }

  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}

